const RATE_LIMIT_WINDOW_MS = 6 * 60 * 60 * 1000 // 6 hours

/**
 * Parse a comma-separated list of API keys from an environment variable.
 */
function parseKeys(raw: string | undefined): string[] {
  return (raw ?? '')
    .split(',')
    .map((key) => key.trim())
    .filter(Boolean)
}

/**
 * Extract the token from an `Authorization: Bearer <token>` header value.
 *
 * Returns `null` if the header is missing or is not a well-formed Bearer token.
 */
function extractBearerToken(authorization: string | null): string | null {
  if (!authorization) return null

  const match = authorization.match(/^Bearer\s+(.+)$/i)
  return match ? match[1].trim() : null
}

type KeyTier = 'basic' | 'override' | null

/**
 * Determine which tier, if any, an API key belongs to. Override keys take
 * precedence over basic keys.
 */
function resolveKeyTier(token: string): KeyTier {
  const overrideKeys = parseKeys(process.env.DOCS_REVALIDATION_OVERRIDE_KEYS)
  if (overrideKeys.includes(token)) return 'override'

  const basicKeys = parseKeys(process.env.DOCS_REVALIDATION_KEYS)
  if (basicKeys.includes(token)) return 'basic'

  return null
}

function getSupabaseClient() {
  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL as string
  const supabaseKey = process.env.SUPABASE_SECRET_KEY as string

  return createClient(supabaseUrl, supabaseKey)
}

/**
 * Handle a request to revalidate one or more cache tags.
 *
 * Requires an `Authorization: Bearer <token>` header. Basic-tier keys are
 * rate-limited to one revalidation every 6 hours; override-tier keys bypass
 * the rate limit.
 */
export async function _handleRevalidateRequest(request: NextRequest | Request): Promise<Response> {
  const authorization = request.headers.get('authorization')
  if (!authorization) {
    return new Response('Missing Authorization header', { status: 401 })
  }

  const token = extractBearerToken(authorization)
  const tier = token ? resolveKeyTier(token) : null
  if (!tier) {
    return new Response('Invalid Authorization header', { status: 401 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return new Response('Malformed request body', { status: 400 })
  }

  const tags = (body as { tags?: unknown })?.tags
  if (!Array.isArray(tags)) {
    return new Response('Malformed request body', { status: 400 })
  }

  const supabase = getSupabaseClient()

  if (tier === 'basic') {
    const since = new Date(Date.now() - RATE_LIMIT_WINDOW_MS).toISOString()
    const { data: recentRevalidations } = await supabase.rpc('get_revalidation_history', {
      since,
    })

    const revalidatedRecently = Array.isArray(recentRevalidations)
      ? recentRevalidations.length > 0
      : Boolean(recentRevalidations)

    if (revalidatedRecently) {
      return new Response('revalidated within the last 6 hours', { status: 429 })
    }
  }

  for (const tag of tags) {
    revalidateTag(tag)
  }

  await supabase.from('revalidation_history').insert({ tags })

  return new Response(null, { status: 204 })
}

export async function POST(request: NextRequest) {
  return _handleRevalidateRequest(request)
